async function seed() {
  console.log("🌱 Seeding game questions...\n");

  // Insert Jeopardy questions
  let jeopardyCount = 0;
  for (const q of jeopardyData) {
    try {
      await pool.execute(
        "INSERT INTO jeopardy_questions (categoryId, clue, answer, value, difficulty) VALUES (?, ?, ?, ?, ?)",
        [q.categoryId, q.clue, q.answer, q.value, q.difficulty]
      );
      jeopardyCount++;
    } catch (err) {
      // Skip duplicates
    }
  }
  console.log(`✅ Seeded ${jeopardyCount} Jeopardy questions`);

  // Insert Trivia Pursuit questions
  let triviaCount = 0;
  for (const q of triviaData) {
    try {
      await pool.execute(
        "INSERT INTO trivia_pursuit_questions (categoryId, question, optionA, optionB, optionC, optionD, correctAnswer, difficulty) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
        [q.categoryId, q.question, q.optionA, q.optionB, q.optionC, q.optionD, q.correctAnswer, q.difficulty]
      );
      triviaCount++;
    } catch (err) {
      // Skip duplicates
    }
  }
  console.log(`✅ Seeded ${triviaCount} Trivia Pursuit questions`);

  console.log(`\n🎉 Total: ${jeopardyCount + triviaCount} questions seeded!`);
  await pool.end();
}

seed().catch(err => {
  console.error("Seed failed:", err);
  process.exit(1);
});
